css.textContent = `:root {
  color-scheme: light;
  --paper: #eeede7;
  --page: #f6f5ef;
  --ink: #1b1b1b;
  --muted: #605f57;
  --line: #cacac2;
  --accent: #2543ef;
  --prose: MemoryBatang, 'Gowun Batang', 'Noto Serif KR', Batang, Georgia, serif;
}
* {box-sizing:border-box}
[hidden] {display:none!important}
body {margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}
.wrap {max-width:760px;margin:auto;padding-inline:clamp(15px,4vw,36px)}
header .wrap {display:grid;grid-template-columns:1fr auto;align-items:center;gap:0 12px;padding-top:16px}
.imprint {font:700 12px/1.35 Arial,sans-serif;letter-spacing:.17em}
h1 {grid-column:1/-1;grid-row:2;font:900 clamp(52px,11vw,92px)/.85 Arial,Helvetica,sans-serif;letter-spacing:-.082em;margin:10px 0 18px}
h2,h3 {line-height:1.35;letter-spacing:-.045em} h2 {font-size:24px} h3 {font-size:17px}
main {padding-bottom:48px}
button,input,select,textarea {font:inherit;color:inherit}
button,select,textarea,input:not([type=checkbox]) {background:var(--page);border:1px solid var(--line);border-radius:2px;min-width:0}
button,select {cursor:pointer;min-height:40px;padding:5px 10px}
button:disabled {opacity:.4;cursor:default}
:focus-visible {outline:2px solid var(--accent);outline-offset:2px}
#close {background:transparent;border:0;grid-column:2;grid-row:1;font-size:14px}
.tabs {display:flex;align-items:stretch;border-block:1px solid var(--ink);margin-bottom:22px}
.tabs button {background:transparent;border:0;padding:9px 16px;position:relative}
.tabs [aria-pressed=true] {color:var(--accent);font-weight:750;box-shadow:inset 0 -3px var(--accent)}
.tabs b {font:600 12px/1.15 monospace}
.tabs #pinsTab {margin-left:auto;order:3}
.tabs #pinsTab[aria-pressed=true] {box-shadow:none;background:var(--accent);color:white;clip-path:polygon(0 0,100% 0,100% 100%,50% 86%,0 100%);padding-bottom:14px;margin-bottom:-7px}
.query {display:flex;border-bottom:2px solid var(--ink);gap:8px;padding-bottom:5px}
.query input {flex:1;background:transparent;border:0;padding:8px 2px;font-size:19px}
.primary {background:var(--accent);color:white;border-color:var(--accent);font-weight:650}
.query button {min-width:58px}
.filters {display:grid;grid-template-columns:1.3fr .85fr 1.15fr;gap:8px;margin:15px 0 22px}
.filters label,.setting label {font-size:14px;font-weight:650}
.filters select,.filters button {display:block;width:100%;padding:5px;margin-top:3px;font-size:14px}
.bar,.meta,.calnav,.actions,.pinrow,.detailtools {display:flex;align-items:center;gap:8px}
.bar,.meta,.calnav {justify-content:space-between}
.meta {border-bottom:1px solid var(--ink);padding-bottom:5px}
#scopeInfo {display:block;margin-block:5px;overflow-wrap:anywhere} #scopeInfo button {min-height:32px;margin-left:8px;font-size:13px}
.meta select {border:0;background:transparent;font-size:14px}
.card {padding:13px 0;border-bottom:1px solid var(--line)}
.openrow {display:block;text-align:left;width:100%;border:0;padding:0;background:transparent}
.openrow small,#stamp {display:block;color:var(--muted);font-size:13px;line-height:1.55}
.timecode {display:block;color:var(--accent);font:650 14px/1.6 ui-monospace,monospace;letter-spacing:.015em}
.openrow p {margin:4px 0 0;font:17px/1.68 var(--prose);overflow-wrap:anywhere}
.hitrow {display:grid;grid-template-columns:minmax(0,1fr) 42px;gap:8px;align-items:center}
.rowpin {background:transparent;border:0;font-size:20px}
.rowpin:hover,.pinrow [aria-pressed=true] {color:var(--accent);background:#e0e4fc}
mark {background:#dee4ff;color:#17288c}
.sub,small,.empty {color:var(--muted);font-size:14px}
.empty {padding:20px 0} #notice {color:var(--accent)} #notice:empty {display:none}
.setting {display:grid;gap:8px;padding:15px 0;border-bottom:1px solid var(--line)}
.setting input {accent-color:var(--accent)}
.actions,.pinrow {flex-wrap:wrap;margin:10px 0}
.pinrow button {font-size:14px}
#pager {margin-top:18px} #summary {scroll-margin-top:1rem}
body:has(#detail:not([hidden])) {background:#f0f0e9}
body:has(#detail:not([hidden])) header .wrap {display:flex;padding-top:4px;padding-bottom:4px;border-bottom:1px solid var(--line)}
body:has(#detail:not([hidden])) header h1 {font-size:21px;letter-spacing:-.06em;margin:0 auto 0 0}
body:has(#detail:not([hidden])) header .imprint {font-size:10px}
#detail {padding-top:10px} #detail .bar {align-items:start}
#title {margin:14px 0 3px;font-size:22px} #body {margin-top:10px;border-top:1px solid var(--ink);padding:14px 0 22px;white-space:pre-wrap;overflow-wrap:anywhere;font:19px/1.95 var(--prose)}
#statusBlock {font-size:14px;color:var(--muted);margin-top:6px}
#statusText {white-space:pre-wrap;overflow-wrap:anywhere}
textarea {width:100%;min-height:45vh;padding:12px;font:17px/1.8 var(--prose)}
dialog {width:min(380px,94vw);background:var(--page);border:1px solid var(--ink);color:var(--ink);padding:16px}
dialog::backdrop {background:#1b1b1b65}
.calnav {margin-top:13px}.calnav input {width:6em;padding:7px}.calnav select {flex:1}
#days {display:grid;grid-template-columns:repeat(7,1fr);gap:3px;margin:12px 0}
#days>* {text-align:center} #days button {padding:0;border:0;background:transparent;min-height:36px}
#days .known {background:#dde2ff;color:#182ca7;font-weight:700} #days .chosen {outline:2px solid var(--accent)} #allDates {display:block;margin-top:12px}
@media(max-width:375px) {.wrap{padding-inline:13px}.filters{gap:5px}.detailtools{gap:4px}#detail .bar button{font-size:14px;padding-inline:7px}.tabs button{padding-inline:12px}}
@font-face{font-family:MemoryBatang;font-style:normal;font-weight:400; font-display:swap;src:url(data:font/woff2;base64,) format("woff2")}`
document.head.append(css)
let state, tab='search', opened, original='', returnTab, returnY=0, page=0, hits=[], day='', month, year
let epoch=0, searchRun=0, allowed=false, saving=false
const pageSize=20
function sameSource(a,b) {
    return a.roomId===b.roomId && (a.id && b.id ? a.id===b.id : a.turn===b.turn)
}
const prefsKey = s => keyFor(s.c,s.current)
function pickTab(next) {
    tab=next
    for(const name of ['search','pins','settings','detail']) show(name,name===next)
    for(const name of ['search','pins','settings']) $(name+'Tab').setAttribute('aria-pressed',String(name===next))
    document.querySelector('.tabs').hidden=next==='detail'
    window.scrollTo(0,0)
}
function empty(id,message) { $(id).replaceChildren(node('p',message,'empty')) }
function option(select, value, name) { select.add(new Option(name,value)) }
async function checked() {
    const fresh=await story()
    if(!state || prefsKey(fresh)!==prefsKey(state)) throw Error('현재 채팅방이 바뀌었습니다. 메뉴를 다시 열어 주세요.')
    return fresh
}
let writeQueue=Promise.resolve()
function change(mutator) {
    if(state?.current.readOnly)throw Error('이 방의 설정을 저장하려면 리수에서 구분되는 방 이름을 지정해 주세요.')
    const identity=state && prefsKey(state)
    const run=async()=>{
        if (!identity || identity!==prefsKey(state)) return
        const fresh=await checked()
        const prefs=await readPrefs(fresh.c.chaId)
        const previous=prefs[fresh.current.id] || {}
        prefs[fresh.current.id]={...previous,...mutator(previous)}
        await api.pluginStorage.setItem(prefix+fresh.c.chaId,JSON.stringify(prefs))
        state=await checked()
        controls()
        if(tab==='pins') renderPins()
        if(tab==='detail') paintBookmark()
    }
    writeQueue=writeQueue.catch(()=>{}).then(run)
    return writeQueue
}
const storedPins = p => p.pins ?? (p.pin?[p.pin]:[])
function pinChange(fn) {return change(p=>({pin:null,pins:fn(storedPins(p).slice())}))}
function pinSource(row) {
    const loc=locateSource(state.rooms,row,true)
    if(!loc)throw Error('연결된 방에서 이 장면을 열 수 없습니다.')
    return {id:loc.room.message[loc.i].chatId || '',turn:loc.i+1,roomId:loc.room.id,roomName:loc.room.name,
        excerpt:row.excerpt && loc.body.includes(row.excerpt) ? row.excerpt.slice(0,420) : loc.body.slice(0,420)}
}
async function togglePin(row) {
    if(state.rooms.find(room=>room.id===row.roomId)?.readOnly)throw Error('이전 형식의 동명 방입니다. 고정하려면 방 이름을 구분해 주세요.')
    const source=pinSource(row)
    if(!state.current.pins.some(p=>sameSource(p,source)) && !locateSource(state.rooms,source))
        throw Error('이 장면은 리수에서 모델 전송을 제외했습니다. 원문은 계속 읽을 수 있습니다.')
    await pinChange(pins=>pins.some(p=>sameSource(p,source))?pins.filter(p=>!sameSource(p,source)):[...pins,source])
}
function controls() {
    const {current,chain,rooms}=state
    const searchRooms=linkedSearchRooms(state)
    setText('count',current.pins.length)
    setText('roomName',state.c.name+' · '+current.name)
    $('auto').checked=allowed && current.sceneRecallAuto
    $('auto').disabled=!allowed
    $('limit').value=String(current.attachLimit)
    $('parent').replaceChildren(new Option('연결하지 않음',''))
    for(const r of rooms) if(r.id && !r.readOnly && !linkedRooms(r,rooms).some(x=>x.id===current.id)) option($('parent'),r.id,r.name)
    $('parent').value=current.sceneRecallParent || ''
    const cold=chain.filter(isArchivedRoom)
    setText('chain',chain.map(r=>r.name).reverse().join(' → ')+(cold.length?' · 리수에서 먼저 열어야 하는 보관된 방: '+cold.map(r=>r.name).join(', '):''))
    const scope=$('scope').value
    $('scope').replaceChildren(new Option('전체 방 ('+rooms.length+'개)',''))
    option($('scope'),'scope:linked','연결한 방만 ('+searchRooms.length+'개)')
    for(const r of rooms)if(r.id)option($('scope'),r.id,r.name)
    $('scope').value=scope==='scope:linked'||rooms.some(r=>r.id===scope)?scope:''
    $('sent').replaceChildren()
    for(const row of sent.get(prefsKey(state)) || [])$('sent').append(card(row,row.excerpt))
    if(!$('sent').children.length)empty('sent','이번 실행에서 첨부한 원문이 없습니다.')
}
function highlight(parent,text,query) {
    parent.textContent=''
    if(!query) {parent.textContent=text;return}
    const escaped=query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')
    let start=0
    for(const m of text.matchAll(new RegExp(escaped,'giu'))) {
        parent.append(document.createTextNode(text.slice(start,m.index)),node('mark',m[0]))
        start=m.index+m[0].length
    }
    parent.append(document.createTextNode(text.slice(start)))
}
function metadata(r) {
    return [r.roomName,r.turn+'번',r.role==='user'?'내 입력':r.role==='char'?'캐릭터':'',r.date?.replaceAll('-','.'),r.time,r.place].filter(Boolean).join(' · ')
}
function card(row,preview,query='',available=true) {
    const box=node('div','','card')
    const open=button('',()=>openScene(row,true),'openrow')
    const line=node('p');highlight(line,preview || '(빈 장면)',query)
    const when=[row.date?.replaceAll('-','.'),row.time].filter(Boolean).join('  ')
    if(when)open.append(node('time',when,'timecode'))
    const where=[row.roomName,row.turn+'번',row.role==='user'?'내 입력':row.role==='char'?'캐릭터':'',row.place].filter(Boolean).join(' · ')
    open.append(node('small',where),line);open.disabled=!available;box.append(open)
    return box
}
function renderPins() {
    const {pins,attachLimit}=state.current
    $('saved').replaceChildren()
    setText('pinHelp','사용 중 '+pins.filter(p=>p.enabled!==false).length+'개 · 위에서부터 최대 '+attachLimit+'개 첨부')
    if(!pins.length)empty('saved','검색한 장면을 열고 ‘📌 원문 고정’을 누르면 여기에 모입니다.')
    pins.forEach((p,i)=>{
        const loc=locateSource(state.rooms,p,true)
        const resolved=loc && selectedScene({sceneRecallPin:p},state.rooms)
        const box=card(resolved || p,resolved?.excerpt || p.excerpt,'',Boolean(loc))
        if(!loc)box.append(node('small','원문을 열 수 없음 · 방 연결 또는 보관 상태를 확인해 주세요.'))
        else if(!resolved)box.append(node('small','리수에서 전송 제외한 대화입니다. 검색과 열람만 가능합니다.'))
        const actions=node('div','','pinrow')
        const active=button(p.enabled===false?'○ 사용 안 함':'● 사용 중',()=>pinChange(list=>list.map(x=>sameSource(x,p)?{...x,enabled:x.enabled===false}:x)))
        active.setAttribute('aria-pressed',String(p.enabled!==false))
        const up=button('↑ 우선순위',()=>pinChange(list=>{
            const n=list.findIndex(x=>sameSource(x,p))
            if(n>0)[list[n-1],list[n]]=[list[n],list[n-1]]
            return list
        }));up.disabled=i===0
        actions.append(active,up,button('고정 해제',()=>pinChange(list=>list.filter(x=>!sameSource(x,p)))))
        box.append(actions);$('saved').append(box)
    })
}
const roomIndexes=new Map()
function invalidate() { epoch++;roomIndexes.clear();searchRun++ }
function selectedRooms() {
    const id=$('scope').value
    if(id==='scope:linked')return linkedSearchRooms(state)
    if(id)return state.rooms.filter(room=>room.id===id)
    return state.rooms
}
async function roomRecords(room,version) {
    if(!Array.isArray(room.message)||isArchivedRoom(room))return []
    const indexed=await core.index(room.message,()=>version!==epoch)
    return indexed.filter(r=>!room.message[r.i].isComment).map(r=>{
        const m=room.message[r.i]
        return {...r,role:m.role,id:m.chatId||'',turn:r.i+1,roomId:room.id,roomName:room.name,
            excerpt:m.chatId?'':sceneBody(m.data).slice(0,90)}
    })
}
async function records(rooms=selectedRooms(),seq) {
    const version=epoch,list=[]
    for(const [i,room] of rooms.entries()) {
        if(version!==epoch || (seq!==undefined && seq!==searchRun))return []
        if(!roomIndexes.has(room.id)) {
            if(seq!==undefined)setText('summary','검색 준비 중 · '+(i+1)+' / '+rooms.length+'방')
            const job=roomRecords(room,version)
            roomIndexes.set(room.id,job)
            job.catch(()=>{if(roomIndexes.get(room.id)===job)roomIndexes.delete(room.id)})
        }
        const rows=await roomIndexes.get(room.id)
        for(const row of rows)list.push(row)
    }
    return list
}
function scoped(list) {
    const role=$('role').value
    return role?list.filter(r=>r.role===role):list
}
let queryUsed=''
async function search() {
    if(!state)return
    const seq=++searchRun
    const q=$('query').value.trim().normalize('NFC')
    setText('summary','대화 검색 중…')
    const list=await records(selectedRooms(),seq)
    if(seq!==searchRun)return
    const filtered=scoped(list)
    const found=q||day?await core.search(filtered,q,day,()=>seq!==searchRun):filtered
    if(seq!==searchRun)return
    queryUsed=q;hits=found;page=0;renderPage()
}
function renderPage() {
    const n=hits.length,pages=Math.max(1,Math.ceil(n/pageSize))
    page=Math.min(page,pages-1)
    setText('summary',(queryUsed||day?'검색 결과 ':'전체 대화 ')+n.toLocaleString()+'개')
    const box=$('hits');box.replaceChildren()
    const scope=$('scope').value
    const searched=selectedRooms()
    const missing=searched.filter(r=>!Array.isArray(r.message)||isArchivedRoom(r))
    const readable=searched.filter(r=>!missing.includes(r))
    const info=$('scopeInfo');info.replaceChildren()
    info.append(document.createTextNode('검색한 방 · '+(readable.map(r=>r.name).join(' · ')||'없음')))
    if(missing.length) info.append(node('div','본문 미로드 · '+missing.map(r=>r.name).join(' · ')+' — 리수에서 해당 방을 한 번 연 뒤 검색창을 다시 열어 주세요.'))
    if(scope==='scope:linked' && searched.length===1 && state.rooms.length>1)
        info.append(button('이전 방 연결',()=>toTab('settings')))
    if(!n) {
        empty('hits',missing.length?'읽을 수 있는 방에서 일치하는 대화가 없습니다.':'일치하는 대화가 없습니다.')
        if(day||$('role').value)$('hits').append(button('날짜·작성자 필터 해제',()=>{
            day='';$('role').value='';setText('calendarOpen','🗓 전체 날짜');searchNow()
        }))
    }
    const start=page*pageSize
    for(let i=start;i<Math.min(n,start+pageSize);i++){
        const row=hits[$('sort').value==='new'?n-i-1:i]
        const item=card(row,row.preview || core.snippet(row.text,queryUsed),queryUsed)
        item.classList.add('hitrow')
        const pinned=state.current.pins.some(p=>sameSource(p,row))
        const pinButton=button(pinned?'📌':'＋',async()=>{
            const loc=locateSource(state.rooms,row,true)
            const pos=queryUsed && loc?loc.body.toLowerCase().indexOf(queryUsed.toLowerCase()):-1
            const start=Math.max(0,pos-90)
            await togglePin({...row,excerpt:loc?.body.slice(start,start+420)||row.excerpt})
            renderPage()
        },'rowpin')
        pinButton.setAttribute('aria-label',metadata(row)+(pinned?' 고정 해제':' 원문 고정'))
        pinButton.title=pinned?'고정 해제':'원문 고정'
        item.append(pinButton);box.append(item)
    }
    setText('page',(page+1)+' / '+pages);$('prevPage').disabled=page===0;$('nextPage').disabled=page===pages-1
    show('pager',pages>1)
}
function searchNow(){search().catch(e=>{if(!e.message.includes('취소'))report(e.message)})}
function paintBookmark() {
    setText('bookmark',state.current.pins.some(p=>sameSource(p,opened))?'📌 고정 해제':'📌 원문 고정')
}
function editMode(on) {
    for(const id of ['draft','save','cancel'])show(id,on)
    for(const id of ['body','prev','next','edit','bookmark'])show(id,!on)
    $('statusBlock').style.display=on?'none':''
    $('back').disabled=on
    if(on){$('draft').value=original;$('draft').focus()}
}
function openScene(row,fromList) {
    const loc=locateSource(state.rooms,row,true)
    if(!loc)throw Error('연결된 방에서 해당 원문을 찾을 수 없습니다.')
    if(fromList){returnTab=tab;returnY=window.scrollY}
    original=loc.room.message[loc.i].data
    const hit=queryUsed && returnTab==='search'?loc.body.toLowerCase().indexOf(queryUsed.toLowerCase()):-1
    const start=Math.max(0,hit-90)
    opened={...row,id:loc.room.message[loc.i].chatId||'',turn:loc.i+1,roomId:loc.room.id,roomName:loc.room.name,
        excerpt:hit>=0?loc.body.slice(start,start+420):row.excerpt||loc.body.slice(0,420)}
    pickTab('detail');editMode(false);paintBookmark()
    setText('title',opened.roomName+' · '+opened.turn+'번 메시지')
    const statusInfo=row.date?row:core.statusDate(original)
    setText('stamp',[statusInfo.date?.replaceAll('-','.'),statusInfo.time,statusInfo.place].filter(Boolean).join(' · '))
    const term=returnTab==='search'?queryUsed:''
    const status=original.match(/<StatusUI\b[^>]*>[\s\S]*?<\/StatusUI\s*>/i)
    const narrative=core.plain(status?original.replace(status[0],''):original)
    const separate=Boolean(status && narrative)
    show('statusBlock',separate)
    if(separate){
        const content=core.plain(status[0])
        highlight($('statusText'),content,term)
        $('statusBlock').open=Boolean(term && content.toLowerCase().includes(term.toLowerCase()) && !narrative.toLowerCase().includes(term.toLowerCase()))
    }
    highlight($('body'),narrative,term)
    $('title').focus({preventScroll:true})
    $('prev').disabled=loc.i<=0;$('next').disabled=loc.i>=loc.room.message.length-1
    window.scrollTo(0,0)
}
async function step(direction) {
    const list=await records(state.rooms.filter(room=>room.id===opened.roomId))
    const n=list.findIndex(r=>r.turn===opened.turn)
    if(n>=0&&list[n+direction])openScene(list[n+direction],false)
}
async function save() {
    if(saving)return
    if(state.rooms.find(r=>r.id===opened.roomId)?.readOnly)throw Error('원문을 수정하려면 리수에서 구분되는 방 이름을 지정해 주세요.')
    const value=$('draft').value
    if(!value.trim())throw Error('빈 원문은 저장할 수 없습니다.')
    saving=true;$('save').disabled=$('cancel').disabled=true
    try {
        if(!await api.requestPluginPermission('dbWrite'))throw Error('리수의 저장 권한이 필요합니다.')
        const fresh=await checked()
        let ordinal=fresh.index
        if(typeof ordinal!=='number'){
            const db=await api.getDatabase(['characters'])
            ordinal=Object.keys(db?.characters||{}).findIndex(k=>db.characters[k]?.chaId===fresh.c.chaId)
        }
        if(ordinal<0)throw Error('캐릭터를 확인하지 못했습니다.')
        const c=await api.getCharacterFromIndex(ordinal)
        if(c?.chaId!==fresh.c.chaId)throw Error('캐릭터가 바뀌었습니다.')
        const i=roomKeys(c.chats).indexOf(opened.roomId)
        if(i<0 || !fresh.rooms.some(r=>r.id===opened.roomId))throw Error('방 연결이 바뀌었습니다.')
        const room=await api.getChatFromIndex(ordinal,i)
        if(!room || (room.id && room.id!==opened.roomId) || (!room.id && (room.name!==c.chats[i].name || room.message?.[0]?.chatId!==c.chats[i].message?.[0]?.chatId)))throw Error('방이 바뀌었습니다. 다시 열어 주세요.')
        const loc=locateSource([{...room,id:opened.roomId}],opened,true)
        if(!loc||room.isStreaming||room.message[loc.i].data!==original)throw Error('원문이 바뀌었거나 전개 중입니다. 다시 열어 주세요.')
        const old=opened
        const preserveLegacyKey=!room.id && loc.i===0
        const id=room.message[loc.i].chatId || (preserveLegacyKey?'':'scene-'+Array.from(crypto.getRandomValues(new Uint32Array(4))).join('-'))
        room.message[loc.i]={...room.message[loc.i],...(id?{chatId:id}:{}),data:value}
        await api.setChatToIndex(ordinal,i,room)
        state=await checked();invalidate()
        const updated={...old,id,excerpt:sceneBody(value).slice(0,420)}
        const result=locateSource(state.rooms,updated,true)
        if(!result||result.room.message[result.i].data!==value)throw Error('저장 결과를 확인할 수 없습니다.')
        if(state.current.pins.some(p=>sameSource(p,old)))await pinChange(list=>list.map(p=>sameSource(p,old)?{...p,id:updated.id,turn:updated.turn,excerpt:updated.excerpt}:p))
        openScene(updated,false);await search();report('원문을 저장했습니다.')
    }finally{saving=false;$('save').disabled=$('cancel').disabled=false}
}
async function calendar() {
    const known=new Set(scoped(await records()).map(r=>r.date).filter(Boolean))
    $('year').value=year;$('month').value=month
    const grid=$('days');grid.replaceChildren()
    for(const w of '일월화수목금토')grid.append(node('small',w))
    const first=new Date(0);first.setUTCFullYear(year,month-1,1)
    for(let i=0;i<first.getUTCDay();i++)grid.append(node('span'))
    for(let n=1;n<=31;n++) {
        const iso=core.date(String(year).padStart(4,'0')+'-'+month+'-'+n)
        if(!iso)break
        const b=button(String(n),()=>chooseDay(iso))
        b.setAttribute('aria-label',iso)
        if(known.has(iso))b.classList.add('known')
        if(day===iso)b.classList.add('chosen')
        grid.append(b)
    }
}
function chooseDay(iso) {
    day=iso;setText('calendarOpen',day?day.replaceAll('-','.'):'🗓 전체 날짜')
    $('calendar').close();searchNow()
}
function moveMonth(delta) {
    const total=(year-1)*12+month-1+delta
    if(total<0 || total>=9999*12)return
    year=Math.floor(total/12)+1;month=total%12+1
    return calendar()
}
async function toTab(next) {
    pickTab(next);report('')
    if(!state){report('채팅방을 열면 해당 캐릭터의 검색과 고정 목록을 사용할 수 있습니다.');return}
    if(next==='search')await search()
    if(next==='pins')renderPins()
    if(next==='settings'){controls();if(!allowed)report('자동 첨부에는 리수의 대화 내용 변경 권한이 필요합니다.')}
}
for(const name of ['search','pins','settings'])$(name+'Tab').onclick=guard(()=>toTab(name))
